/**
 * WebSocket client for MONOTERMINAL protocol communication
 * Phase 1: WebSocket with Protocol Buffers
 * Phase 2: Will add WebRTC DataChannel P2P support
 */

export enum ConnectionState {
  DISCONNECTED = 'disconnected',
  CONNECTING = 'connecting',
  CONNECTED = 'connected',
  RECONNECTING = 'reconnecting',
  ERROR = 'error',
}

export interface ConnectionConfig {
  url: string;
  autoReconnect?: boolean;
  reconnectInterval?: number; // ms
  maxReconnectAttempts?: number;
  authToken?: string; // JWT authentication token (passed via query param in Phase 1)
}

export interface MessageHandler {
  (data: ArrayBuffer): void;
}

export class WebSocketClient {
  private ws: WebSocket | null = null;
  private config: Required<ConnectionConfig>;
  private messageHandlers: Set<MessageHandler> = new Set();
  private stateListeners: Set<(state: ConnectionState) => void> = new Set();
  private reconnectAttempts = 0;
  private reconnectTimer: number | null = null;
  private state: ConnectionState = ConnectionState.DISCONNECTED;

  constructor(config: ConnectionConfig) {
    this.config = {
      autoReconnect: true,
      reconnectInterval: 3000, // 3s default, targeting <10s total per SRS §7.1
      maxReconnectAttempts: 5,
      authToken: '',
      ...config,
    };
  }

  connect(): void {
    if (this.state === ConnectionState.CONNECTED || this.state === ConnectionState.CONNECTING) {
      return;
    }

    this.setState(
      this.reconnectAttempts > 0 ? ConnectionState.RECONNECTING : ConnectionState.CONNECTING
    );

    try {
      // Construct WebSocket URL with optional auth parameter
      const url = this.config.authToken
        ? `${this.config.url}?auth=${encodeURIComponent(this.config.authToken)}`
        : this.config.url;

      this.ws = new WebSocket(url);
      this.ws.binaryType = 'arraybuffer';

      this.ws.onopen = () => {
        console.log('WebSocket connected');
        this.reconnectAttempts = 0;
        this.setState(ConnectionState.CONNECTED);
      };

      this.ws.onmessage = (event) => {
        if (event.data instanceof ArrayBuffer) {
          this.handleMessage(event.data);
        } else {
          console.warn('Received non-binary message, ignoring');
        }
      };

      this.ws.onerror = (error) => {
        console.error('WebSocket error:', error);
        this.setState(ConnectionState.ERROR);
      };

      this.ws.onclose = (event) => {
        console.log('WebSocket closed:', event.code, event.reason);
        this.ws = null;

        if (
          this.config.autoReconnect &&
          this.reconnectAttempts < this.config.maxReconnectAttempts
        ) {
          this.scheduleReconnect();
        } else {
          this.setState(ConnectionState.DISCONNECTED);
        }
      };
    } catch (error) {
      console.error('Failed to create WebSocket:', error);
      this.setState(ConnectionState.ERROR);
    }
  }

  disconnect(): void {
    this.config.autoReconnect = false;
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }

    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }

    this.setState(ConnectionState.DISCONNECTED);
  }

  send(data: ArrayBuffer): void {
    if (this.ws && this.state === ConnectionState.CONNECTED) {
      this.ws.send(data);
    } else {
      console.warn('Cannot send: WebSocket not connected');
    }
  }

  onMessage(handler: MessageHandler): () => void {
    this.messageHandlers.add(handler);
    return () => {
      this.messageHandlers.delete(handler);
    };
  }

  onStateChange(listener: (state: ConnectionState) => void): () => void {
    this.stateListeners.add(listener);
    return () => {
      this.stateListeners.delete(listener);
    };
  }

  getState(): ConnectionState {
    return this.state;
  }

  private handleMessage(data: ArrayBuffer): void {
    // For now, just pass raw data to handlers
    // TODO: Add Protocol Buffer decoding when proto definitions are ready
    this.messageHandlers.forEach((handler) => {
      try {
        handler(data);
      } catch (error) {
        console.error('Message handler error:', error);
      }
    });
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer !== null) {
      return;
    }

    this.reconnectAttempts++;
    const delay = this.config.reconnectInterval * Math.min(this.reconnectAttempts, 3); // Exponential backoff, capped

    console.log(
      `Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts}/${this.config.maxReconnectAttempts})`
    );

    this.reconnectTimer = window.setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, delay);
  }

  private setState(newState: ConnectionState): void {
    if (this.state !== newState) {
      this.state = newState;
      this.stateListeners.forEach((listener) => {
        try {
          listener(newState);
        } catch (error) {
          console.error('State listener error:', error);
        }
      });
    }
  }
}

