import { useState, useEffect } from 'react';
import './MonomindPanel.css';

interface MonomindPanelProps {
  sessionId?: string;
  isVisible: boolean;
  onClose: () => void;
}

/**
 * Embedded Monomind dashboard panel
 * Per SRS §2.4.2: Lives inside the same web client, same JWT auth
 * Shows org/agent status, health checks, and upgrade controls
 */
export function MonomindPanel({ sessionId, isVisible, onClose }: MonomindPanelProps) {
  const [healthStatus, setHealthStatus] = useState<'unknown' | 'healthy' | 'warning' | 'error'>(
    'unknown'
  );
  const [lastCheck, setLastCheck] = useState<Date | null>(null);

  useEffect(() => {
    if (isVisible && sessionId) {
      // TODO: Fetch actual monomind status from master daemon
      // For now, show placeholder
      checkHealth();
    }
  }, [isVisible, sessionId]);

  const checkHealth = async () => {
    // TODO: Call monomind health check API via master daemon
    // Placeholder implementation
    setHealthStatus('unknown');
    setLastCheck(new Date());
  };

  const handleUpgrade = () => {
    // TODO: Trigger monomind upgrade via master daemon
    // Will require user confirmation per SRS §2.4.3
    alert('Upgrade feature will be implemented when monomind-bridge API is ready');
  };

  if (!isVisible) return null;

  return (
    <div className="monomind-panel">
      <div className="panel-header">
        <h2>Monomind Dashboard</h2>
        <button className="close-btn" onClick={onClose} aria-label="Close panel">
          ×
        </button>
      </div>

