// PTY (Pseudo-Terminal) Management
// Platform-specific implementations for terminal session management
//
// SRS Reference: §2.1.2 PTY Management [D1.2]
// - Windows: ConPTY API (§2.1.2.3 [D1.2.3])
// - Linux: posix_openpt (§2.1.2.1 [D1.2.1]) - Phase 3
// - macOS: openpty BSD (§2.1.2.2 [D1.2.2]) - Phase 3

pub mod error;

#[cfg(windows)]
pub mod windows;

#[cfg(windows)]
pub use windows::{WindowsPty, PtyHandle};

use error::PtyError;
use std::path::PathBuf;

/// Terminal dimensions (columns, rows)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PtySize {
    pub cols: u16,
    pub rows: u16,
}

impl Default for PtySize {
    fn default() -> Self {
        Self {
            cols: 80,
            rows: 24,
        }
    }
}

/// Configuration for creating a new PTY session
#[derive(Debug, Clone)]
pub struct PtyConfig {
    /// Terminal size
    pub size: PtySize,
    /// Shell executable path (e.g., "powershell.exe", "bash")
    pub shell: PathBuf,
    /// Working directory for the shell process
    pub working_dir: PathBuf,
    /// Environment variables for the shell process
    pub env: Vec<(String, String)>,
}

impl Default for PtyConfig {
    fn default() -> Self {
        Self {
            size: PtySize::default(),
            shell: Self::default_shell(),
            working_dir: std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
            env: Vec::new(),
        }
    }
}

impl PtyConfig {
    /// Get the default shell for the current platform
    #[cfg(windows)]
    fn default_shell() -> PathBuf {
        PathBuf::from("powershell.exe")
    }

    #[cfg(not(windows))]
    fn default_shell() -> PathBuf {
        PathBuf::from("/bin/bash")
    }
}

/// Platform-agnostic PTY trait
///
/// This trait abstracts over platform-specific PTY implementations,
/// allowing the session manager to work with different backends.
pub trait Pty: Send + Sync {
    /// Spawn a new PTY session with the given configuration
    fn spawn(config: PtyConfig) -> Result<Self, PtyError>
    where
        Self: Sized;

    /// Resize the PTY to new dimensions
    fn resize(&mut self, size: PtySize) -> Result<(), PtyError>;

    /// Read data from the PTY (non-blocking)
    /// Returns the number of bytes read into the buffer
    fn read(&mut self, buf: &mut [u8]) -> Result<usize, PtyError>;

    /// Write data to the PTY
    fn write(&mut self, buf: &[u8]) -> Result<usize, PtyError>;

    /// Check if the child process is still running
    fn is_alive(&self) -> bool;

    /// Get the child process ID
    fn child_pid(&self) -> Option<u32>;

    /// Gracefully shutdown the PTY session
    /// Sends a terminate signal and waits for clean exit
    fn shutdown(&mut self) -> Result<(), PtyError>;

    /// Force-kill the PTY session (last resort)
    fn kill(&mut self) -> Result<(), PtyError>;
}

