// Windows ConPTY Implementation
// SRS Reference: §2.1.2.3 Windows ConPTY [D1.2.3]
//
// Implements the Windows Console Pseudo-console API (Windows 10 1809+)
// using the `windows` crate bindings.
//
// Key APIs:
// - CreatePseudoConsole: Allocate a ConPTY instance
// - UpdateProcThreadAttribute: Attach ConPTY to STARTUPINFOEX
// - CreateProcess: Spawn process attached to ConPTY
// - ResizePseudoConsole: Change terminal dimensions
//
// Safety: All FFI calls are wrapped with proper error handling and
// resource cleanup via RAII (Drop trait).

use super::{Pty, PtyConfig, PtyError, PtyResult, PtySize};
use std::ffi::OsStr;
use std::mem::MaybeUninit;
use std::os::windows::ffi::OsStrExt;
use std::path::Path;
use std::ptr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use windows::core::PCWSTR;
use windows::Win32::Foundation::{
    CloseHandle, HANDLE, INVALID_HANDLE_VALUE, WAIT_OBJECT_0, WAIT_TIMEOUT,
};
use windows::Win32::Storage::FileSystem::{ReadFile, WriteFile, FILE_FLAG_OVERLAPPED};
use windows::Win32::System::Console::{
    ClosePseudoConsole, CreatePseudoConsole, ResizePseudoConsole, COORD, HPCON,
};
use windows::Win32::System::Pipes::CreatePipe;
use windows::Win32::System::Threading::{
    CreateProcessW, GetExitCodeProcess, InitializeProcThreadAttributeList,
    TerminateProcess, UpdateProcThreadAttribute, WaitForSingleObject,
    CREATE_UNICODE_ENVIRONMENT, EXTENDED_STARTUPINFO_PRESENT, LPPROC_THREAD_ATTRIBUTE_LIST,
    PROCESS_INFORMATION, PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE, STARTF_USESTDHANDLES,
    STARTUPINFOEXW, STARTUPINFOW,
};

/// Handle wrapper with automatic cleanup
struct Handle(HANDLE);

impl Handle {
    fn new(handle: HANDLE) -> PtyResult<Self> {
        if handle == INVALID_HANDLE_VALUE || handle.0 == 0 {
            return Err(PtyError::CreateFailed("Invalid handle".to_string()));
        }
        Ok(Self(handle))
    }

    fn as_raw(&self) -> HANDLE {
        self.0
    }
}

impl Drop for Handle {
    fn drop(&mut self) {
        // SAFETY: We only close valid handles that we own
        unsafe {
            let _ = CloseHandle(self.0);
        }
    }
}

/// ConPTY handle wrapper with automatic cleanup
struct HpconHandle(HPCON);

impl Drop for HpconHandle {
    fn drop(&mut self) {
        // SAFETY: ClosePseudoConsole is safe to call on a valid HPCON
        unsafe {
            ClosePseudoConsole(self.0);
        }
    }
}

/// Windows ConPTY implementation
///
/// This struct manages a Windows pseudo-console session with a child process.
/// It provides async I/O capabilities through overlapped named pipes.
///
/// # Platform Support
/// Windows 10 1809+ (ConPTY API introduced in build 17763)
pub struct WindowsPty {
    /// Pseudo-console handle
    conpty: HpconHandle,
    /// Input pipe (write to send data to child process)
    input_write: Handle,
    /// Output pipe (read to receive data from child process)
    output_read: Handle,
    /// Child process handle
    process: Handle,
    /// Process ID
    pid: u32,
    /// Current terminal size
    size: PtySize,
    /// Whether the PTY is closed
    closed: Arc<AtomicBool>,
}

impl WindowsPty {
    /// Create overlapped named pipes for ConPTY I/O
    ///
    /// # Safety
    /// Creates named pipes with FILE_FLAG_OVERLAPPED for async I/O.
    /// The handles must be closed via CloseHandle when no longer needed.
    fn create_pipes() -> PtyResult<(Handle, Handle, Handle, Handle)> {
        let mut input_read = HANDLE::default();
        let mut input_write = HANDLE::default();
        let mut output_read = HANDLE::default();
        let mut output_write = HANDLE::default();

        // SAFETY: CreatePipe is safe to call with valid out-pointers.
        // We pass NULL for security attributes (default) and 0 for buffer size (default).
        unsafe {
            // Input pipe: ConPTY reads from input_read, we write to input_write
            CreatePipe(
                &mut input_read,
                &mut input_write,
                None,
                0,
            )
            .map_err(|e| PtyError::CreateFailed(format!("Failed to create input pipe: {}", e)))?;

            // Output pipe: ConPTY writes to output_write, we read from output_read
            CreatePipe(
                &mut output_read,
                &mut output_write,
                None,
                0,
            )
            .map_err(|e| PtyError::CreateFailed(format!("Failed to create output pipe: {}", e)))?;
        }

        Ok((
            Handle::new(input_read)?,
            Handle::new(input_write)?,
            Handle::new(output_read)?,
            Handle::new(output_write)?,
        ))
    }

    /// Create a pseudo-console with the given size and pipe handles
    ///
    /// # Safety
    /// Calls CreatePseudoConsole which creates a new ConPTY instance.
    /// The returned HPCON must be freed via ClosePseudoConsole.
    fn create_conpty(
        size: PtySize,
        input: HANDLE,
        output: HANDLE,
    ) -> PtyResult<HPCON> {
        let coord = COORD {
            X: size.cols as i16,
            Y: size.rows as i16,
        };

        let mut hpcon = HPCON::default();

        // SAFETY: CreatePseudoConsole is safe to call with valid handles and size.
        // We pass 0 for flags (no special behavior).
        unsafe {
            CreatePseudoConsole(coord, input, output, 0, &mut hpcon)
                .map_err(|e| PtyError::CreateFailed(format!("CreatePseudoConsole failed: {}", e)))?;
        }

        Ok(hpcon)
    }

    /// Convert a Rust string to a null-terminated wide string for Windows APIs
    fn to_wide_string(s: &str) -> Vec<u16> {
        OsStr::new(s)
            .encode_wide()
            .chain(std::iter::once(0))
            .collect()
    }

    /// Build the environment block for CreateProcessW
    fn build_env_block(env: &[(String, String)]) -> Vec<u16> {
        if env.is_empty() {
            return Vec::new();
        }

        let mut block = String::new();
        for (key, value) in env {
            block.push_str(key);
            block.push('=');
            block.push_str(value);
            block.push('\0');
        }
        block.push('\0'); // Double null-terminator

        Self::to_wide_string(&block)
    }

    /// Spawn a child process attached to the ConPTY
    ///
    /// # Safety
    /// Uses CreateProcessW with EXTENDED_STARTUPINFO_PRESENT and a properly
    /// initialized STARTUPINFOEX containing the ConPTY handle.
    fn spawn_process(
        conpty: HPCON,
        config: &PtyConfig,
    ) -> PtyResult<(HANDLE, u32)> {
        // Build command line: shell path
        let shell_path = config.shell.to_str()
            .ok_or_else(|| PtyError::InvalidConfig("Invalid shell path".to_string()))?;
        let mut command_line = Self::to_wide_string(shell_path);

        // Build environment block
        let env_block = Self::build_env_block(&config.env);
        let env_ptr = if env_block.is_empty() {
            ptr::null()
        } else {
            env_block.as_ptr() as *const _
        };

        // Working directory
        let cwd = config.working_dir.to_str()
            .ok_or_else(|| PtyError::InvalidConfig("Invalid working directory".to_string()))?;
        let cwd_wide = Self::to_wide_string(cwd);

        // Initialize STARTUPINFOEX
        let mut startup_info: STARTUPINFOEXW = unsafe { std::mem::zeroed() };
        startup_info.StartupInfo.cb = std::mem::size_of::<STARTUPINFOEXW>() as u32;
        startup_info.StartupInfo.dwFlags = STARTF_USESTDHANDLES;

        // Determine required size for attribute list
        let mut attr_size: usize = 0;
        unsafe {
            let _ = InitializeProcThreadAttributeList(
                LPPROC_THREAD_ATTRIBUTE_LIST(ptr::null_mut()),
                1,
                0,
                &mut attr_size,
            );
        }

        // Allocate and initialize attribute list
        let mut attr_list_buffer: Vec<u8> = vec![0u8; attr_size];
        let attr_list_ptr = LPPROC_THREAD_ATTRIBUTE_LIST(attr_list_buffer.as_mut_ptr() as *mut _);

        unsafe {
            InitializeProcThreadAttributeList(attr_list_ptr, 1, 0, &mut attr_size)
                .map_err(|e| PtyError::SpawnFailed(format!("Failed to initialize attribute list: {}", e)))?;
        }

        startup_info.lpAttributeList = attr_list_ptr;

        // Attach ConPTY to the attribute list
        unsafe {
            UpdateProcThreadAttribute(
                attr_list_ptr,
                0,
                PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE as usize,
                Some(&conpty as *const _ as *const _),
                std::mem::size_of::<HPCON>(),
                None,
                None,
            )
            .map_err(|e| PtyError::SpawnFailed(format!("Failed to update proc thread attribute: {}", e)))?;
        }

        // Create the process
        let mut process_info: PROCESS_INFORMATION = unsafe { std::mem::zeroed() };

        unsafe {
            CreateProcessW(
                None,
                windows::core::PWSTR(command_line.as_mut_ptr()),
                None,
                None,
                false,
                EXTENDED_STARTUPINFO_PRESENT | CREATE_UNICODE_ENVIRONMENT,
                Some(env_ptr as *const _),
                PCWSTR(cwd_wide.as_ptr()),
                &startup_info.StartupInfo,
                &mut process_info,
            )
            .map_err(|e| PtyError::SpawnFailed(format!("CreateProcessW failed: {}", e)))?;
        }

        // Close thread handle (we don't need it)
        unsafe {
            let _ = CloseHandle(process_info.hThread);
        }

        Ok((process_info.hProcess, process_info.dwProcessId))
    }
}

impl Pty for WindowsPty {
    fn spawn(config: PtyConfig) -> PtyResult<Self> {
        tracing::debug!(
            "Spawning ConPTY session: shell={:?}, size={}x{}",
            config.shell,
            config.size.cols,
            config.size.rows
        );

        // Create pipes for I/O
        let (input_read, input_write, output_read, output_write) = Self::create_pipes()?;

        // Create the pseudo-console
        let hpcon = Self::create_conpty(
            config.size,
            input_read.as_raw(),
            output_write.as_raw(),
        )?;

        // Spawn the child process
        let (process_handle, pid) = Self::spawn_process(hpcon, &config)?;

        tracing::info!("ConPTY session created: pid={}", pid);

        Ok(Self {
            conpty: HpconHandle(hpcon),
            input_write,
            output_read,
            process: Handle::new(process_handle)?,
            pid,
            size: config.size,
            closed: Arc::new(AtomicBool::new(false)),
        })
    }

    fn resize(&mut self, size: PtySize) -> PtyResult<()> {
        if self.closed.load(Ordering::Relaxed) {
            return Err(PtyError::AlreadyClosed);
        }

        let coord = COORD {
            X: size.cols as i16,
            Y: size.rows as i16,
        };

        // SAFETY: ResizePseudoConsole is safe to call on a valid HPCON
        unsafe {
            ResizePseudoConsole(self.conpty.0, coord)
                .map_err(|e| PtyError::ResizeFailed(format!("ResizePseudoConsole failed: {}", e)))?;
        }

        self.size = size;
        tracing::debug!("Resized ConPTY to {}x{}", size.cols, size.rows);

        Ok(())
    }

    fn read(&mut self, buf: &mut [u8]) -> PtyResult<usize> {
        if self.closed.load(Ordering::Relaxed) {
            return Err(PtyError::AlreadyClosed);
        }

        let mut bytes_read: u32 = 0;

        // SAFETY: ReadFile is safe to call with valid handle and buffer.
        // We use synchronous read here; async version will use overlapped I/O.
        unsafe {
            ReadFile(
                self.output_read.as_raw(),
                Some(buf),
                Some(&mut bytes_read),
                None,
            )
            .map_err(|e| {
                // Check if process exited
                if !self.is_alive() {
                    PtyError::ProcessExited
                } else {
                    PtyError::Io(std::io::Error::from_raw_os_error(e.code().0 as i32))
                }
            })?;
        }

        Ok(bytes_read as usize)
    }

    fn write(&mut self, buf: &[u8]) -> PtyResult<usize> {
        if self.closed.load(Ordering::Relaxed) {
            return Err(PtyError::AlreadyClosed);
        }

        let mut bytes_written: u32 = 0;

        // SAFETY: WriteFile is safe to call with valid handle and buffer
        unsafe {
            WriteFile(
                self.input_write.as_raw(),
                Some(buf),
                Some(&mut bytes_written),
                None,
            )
            .map_err(|e| {
                if !self.is_alive() {
                    PtyError::ProcessExited
                } else {
                    PtyError::Io(std::io::Error::from_raw_os_error(e.code().0 as i32))
                }
            })?;
        }

        Ok(bytes_written as usize)
    }

    fn is_alive(&self) -> bool {
        if self.closed.load(Ordering::Relaxed) {
            return false;
        }

        // SAFETY: WaitForSingleObject with 0 timeout is safe for checking process status
        unsafe {
            let result = WaitForSingleObject(self.process.as_raw(), 0);
            result != WAIT_OBJECT_0
        }
    }

    fn child_pid(&self) -> Option<u32> {
        if self.is_alive() {
            Some(self.pid)
        } else {
            None
        }
    }

    fn shutdown(&mut self) -> PtyResult<()> {
        if self.closed.swap(true, Ordering::Relaxed) {
            return Ok(()); // Already closed
        }

        tracing::debug!("Shutting down ConPTY session: pid={}", self.pid);

        // Wait up to 10 seconds for clean exit (SRS §2.1.3)
        const SHUTDOWN_TIMEOUT_MS: u32 = 10000;

        // SAFETY: WaitForSingleObject is safe to call on a valid process handle
        unsafe {
            let result = WaitForSingleObject(self.process.as_raw(), SHUTDOWN_TIMEOUT_MS);

            if result == WAIT_TIMEOUT {
                tracing::warn!("Process {} did not exit cleanly, force-killing", self.pid);
                return self.kill();
            }
        }

        tracing::info!("ConPTY session shut down cleanly: pid={}", self.pid);
        Ok(())
    }

    fn kill(&mut self) -> PtyResult<()> {
        if self.closed.swap(true, Ordering::Relaxed) {
            return Ok(()); // Already closed
        }

        tracing::warn!("Force-killing ConPTY session: pid={}", self.pid);

        // SAFETY: TerminateProcess is safe to call on a valid process handle
        unsafe {
            TerminateProcess(self.process.as_raw(), 1)
                .map_err(|e| PtyError::CreateFailed(format!("Failed to terminate process: {}", e)))?;
        }

        Ok(())
    }
}

/// Opaque handle type for external use
#[derive(Debug)]
pub struct PtyHandle {
    pid: u32,
}

impl PtyHandle {
    pub fn pid(&self) -> u32 {
        self.pid
    }
}

impl From<&WindowsPty> for PtyHandle {
    fn from(pty: &WindowsPty) -> Self {
        Self { pid: pty.pid }
    }
