            message: Some(Message::OutputData(OutputData {
                data: data.clone(),
                sequence: 0,
                compression: CompressionType::None,
            })),
        };

        let encoded = encode_envelope(&original).unwrap();
        let decoded = decode_envelope(&encoded).unwrap();

        prop_assert_eq!(original, decoded);
    }

