    fn fuzz_compression_preserves_data(
        data in prop::collection::vec(any::<u8>(), 0..65536)
    ) {
        let compressed = compress_zstd(&data).unwrap();
        let decompressed = decompress_zstd(&compressed).unwrap();
        prop_assert_eq!(data, decompressed);
    }
