// Ring Buffer for in-memory scrollback
// SRS §2.1.3: 10k lines capacity, ~1MB in-memory (Phase 1 only, no SQLite)

use super::session::Line;

/// Ring buffer for scrollback storage
/// Capacity: 10,000 lines (per SRS §2.1.3, Phase 1 MVP)
pub struct RingBuffer<T> {
    buffer: Vec<Option<T>>,
    capacity: usize,
    head: usize,
    len: usize,
    next_line_number: u64,
}

impl<T: Clone> RingBuffer<T> {
    /// Create new ring buffer with given capacity
    pub fn new(capacity: usize) -> Self {
        let mut buffer = Vec::with_capacity(capacity);
        buffer.resize_with(capacity, || None);

        Self {
            buffer,
            capacity,
            head: 0,
            len: 0,
            next_line_number: 0,
        }
    }

    /// Push new item (overwrites oldest if full)
    pub fn push(&mut self, mut item: T) where T: AsMut<Line> {
        // Set line number
        let line = item.as_mut();
        line.line_number = self.next_line_number;
        self.next_line_number += 1;

        let index = (self.head + self.len) % self.capacity;
        self.buffer[index] = Some(item);

        if self.len < self.capacity {
            self.len += 1;
        } else {
            // Buffer full, advance head (overwrite oldest)
            self.head = (self.head + 1) % self.capacity;
        }
    }

    /// Get number of items in buffer
    pub fn len(&self) -> usize {
        self.len
    }

    /// Check if buffer is empty
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Check if buffer is full
    pub fn is_full(&self) -> bool {
        self.len == self.capacity
    }

    /// Iterate over items in chronological order (oldest to newest)
    pub fn iter(&self) -> impl Iterator<Item = &T> {
        let head = self.head;
        let len = self.len;
        let capacity = self.capacity;

        (0..len).filter_map(move |i| {
            let index = (head + i) % capacity;
            self.buffer.get(index).and_then(|opt| opt.as_ref())
        })
    }

    /// Clear all items
    pub fn clear(&mut self) {
        for item in self.buffer.iter_mut() {
            *item = None;
        }
        self.head = 0;
        self.len = 0;
    }
}

impl RingBuffer<Line> {
    /// Specialized push for Line type
    pub fn push_line(&mut self, data: Vec<u8>) {
        let mut line = Line {
            data,
            line_number: 0, // Will be set by push()
        };

        let index = (self.head + self.len) % self.capacity;
        line.line_number = self.next_line_number;
        self.next_line_number += 1;

        self.buffer[index] = Some(line);

        if self.len < self.capacity {
            self.len += 1;
        } else {
            self.head = (self.head + 1) % self.capacity;
        }
    }
}

// Implement AsMut<Line> for Line
impl AsMut<Line> for Line {
    fn as_mut(&mut self) -> &mut Line {
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_ring_buffer_basic() {
        let mut buf = RingBuffer::<i32>::new(3);
        assert!(buf.is_empty());
        assert_eq!(buf.len(), 0);
    }

    #[test]
    fn test_ring_buffer_push() {
        let mut buf = RingBuffer::new(3);

        buf.push_line(b"line1".to_vec());
        buf.push_line(b"line2".to_vec());
        buf.push_line(b"line3".to_vec());

        assert_eq!(buf.len(), 3);
        assert!(buf.is_full());

        let lines: Vec<_> = buf.iter().collect();
        assert_eq!(lines.len(), 3);
        assert_eq!(lines[0].data, b"line1");
        assert_eq!(lines[1].data, b"line2");
        assert_eq!(lines[2].data, b"line3");
    }

    #[test]
    fn test_ring_buffer_overflow() {
        let mut buf = RingBuffer::new(3);

        buf.push_line(b"line1".to_vec());
        buf.push_line(b"line2".to_vec());
        buf.push_line(b"line3".to_vec());
        buf.push_line(b"line4".to_vec()); // Overwrites line1

        assert_eq!(buf.len(), 3);

        let lines: Vec<_> = buf.iter().collect();
        assert_eq!(lines[0].data, b"line2");
        assert_eq!(lines[1].data, b"line3");
        assert_eq!(lines[2].data, b"line4");
    }

    #[test]
    fn test_ring_buffer_line_numbers() {
        let mut buf = RingBuffer::new(3);

        buf.push_line(b"line1".to_vec());
        buf.push_line(b"line2".to_vec());
        buf.push_line(b"line3".to_vec());
        buf.push_line(b"line4".to_vec());

        let lines: Vec<_> = buf.iter().collect();
        assert_eq!(lines[0].line_number, 1); // line2
        assert_eq!(lines[1].line_number, 2); // line3
        assert_eq!(lines[2].line_number, 3); // line4
    }

    #[test]
    fn test_ring_buffer_clear() {
        let mut buf = RingBuffer::new(3);

        buf.push_line(b"line1".to_vec());
        buf.push_line(b"line2".to_vec());

        assert_eq!(buf.len(), 2);

        buf.clear();
        assert!(buf.is_empty());
        assert_eq!(buf.len(), 0);
    }
}

