```rust
#[async_trait]
pub trait AuthManager: Send + Sync {
    async fn verify_jwt(&self, token: &str) -> Result<Claims, AuthError>;
    async fn issue_jwt(&self, user_id: &str) -> Result<JwtPair, AuthError>;
    async fn refresh_jwt(&self, refresh_token: &str) -> Result<JwtPair, AuthError>;  // ← Added
    fn verify_challenge(
        &self,
        challenge: &[u8],
        signature: &[u8; 64],       // ← Sized arrays
        public_key: &[u8; 32],
    ) -> Result<String, AuthError>;  // ← Returns user_id
}

pub struct Claims {
    pub user_id: String,
    pub issued_at: i64,
    pub expires_at: i64,
    pub scope: Vec<String>,
}

pub struct JwtPair {
    pub access_token: String,
    pub refresh_token: String,
}

#[async_trait]
pub trait RateLimiter: Send + Sync {
    fn check_connection(&self, peer_addr: &SocketAddr) -> Result<(), RateLimitError>;
    fn check_auth_attempt(&self, user_id: &str) -> Result<(), RateLimitError>;
    fn record_success(&self, peer_addr: &SocketAddr);  // ← Added
}

#[derive(Debug, Error)]
pub enum AuthError {
    #[error("Invalid JWT: {0}")]
    InvalidJwt(String),

    #[error("JWT expired")]
    Expired,

    #[error("Signature verification failed")]
    InvalidSignature,

    #[error("User not found: {0}")]
    UserNotFound(String),

    #[error("Internal error: {0}")]
    Internal(String),
}

#[derive(Debug, Error)]
pub enum RateLimitError {
    #[error("Connection rate limit exceeded")]
    TooManyConnections,

    #[error("Auth attempt rate limit exceeded")]
    TooManyAttempts,
}
```

